def text_lowercase_underscore(input_string):
    split_string = input_string.split('_')
    for part in split_string:
        if not part.islower():
            return False
    return True

def remove_Occ(string, char):
    first_index = string.find(char)
    if first_index != -1:
        string = string[:first_index] + string[first_index + 1:]
        last_index = string.rfind(char)
        if last_index != -1:
            string = string[:last_index] + string[last_index + 1:]
    return string

